public class CSVParser_getHeaderMap_TriageGen0Test {



    @Test
    public void testGetHeaderMapWithNoHeader() throws IOException {
        String csvContent = "1,John,30\n2,Jane,25";
        CSVFormat format = CSVFormat.DEFAULT; // No header defined

        try (CSVParser parser = CSVParser.parse(csvContent, format)) {
            Map<String, Integer> headerMap = parser.getHeaderMap();

            assertTrue("Header map should be empty when no header is defined", headerMap.isEmpty());
        }
    }




